/** @description Proves the caller-visible greeting contract. */

import { describe, expect, it } from 'vitest';

import { createGreeting } from './index';

describe('createGreeting', () => {
	it('creates a greeting for a non-empty name', () => {
		expect(createGreeting({ name: 'Ada' })).toEqual({ ok: true, value: 'Hello, Ada!' });
	});

	it('returns a typed failure for a blank name', () => {
		expect(createGreeting({ name: '   ' })).toEqual({
			ok: false,
			error: {
				code: 'EMPTY_NAME',
				message: 'A non-empty name is required.',
			},
		});
	});
});

