```ts
/** @description Proves the caller-visible display-name contract. */

import { describe, expect, it } from 'vitest';

import { parseDisplayName } from './index';

describe('parseDisplayName', () => {
	it('accepts a non-empty display name', () => {
		// Given: a caller-supplied display name with content
		// When: parseDisplayName validates it
		// Then: parseDisplayName returns the trimmed value
		expect(parseDisplayName('Ada')).toEqual({ ok: true, value: 'Ada' });
	});

	it('returns a typed failure for an empty display name', () => {
		// Given: a display name that is empty after trimming
		// When: parseDisplayName validates it
		// Then: parseDisplayName returns EMPTY_DISPLAY_NAME with a caller-facing message
		expect(parseDisplayName('   ')).toEqual({
			ok: false,
			error: {
				code: 'EMPTY_DISPLAY_NAME',
				message: 'A non-empty display name is required.',
			},
		});
	});
});
```

Rule 4.1/profile: `describe` names public unit, `it` names observable behavior, Given/When/Then carry example, rejection asserts message not just throw-happened. Swap `parseDisplayName`/import path for the real helper's name and location.

